//! Canonical area alt reflection retains actual DOMString attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><area id=area alt=2026-11-24><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://area-alt.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn area_alt_canonical_interface_descriptors_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),C=HTMLAreaElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'alt');if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get alt'||a.set.name!=='set alt'||Object.hasOwn(x,'alt')||x.alt!=='2026-11-24'||x.textContent!=='')throw 'canonical area metadata';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal area construction';"#);}
#[test]
fn area_alt_exact_native_setter_aliases_and_observer_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),a=x.getAttributeNode('alt'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.alt='A\ud800Z';var records=watch.takeRecords();if(x.alt!=='A\ud800Z'||a.value!==x.alt||x.getAttributeNode('alt')!==a||records.length!==1||records[0].attributeName!=='alt'||records[0].oldValue!=='2026-11-24'||x.textContent!=='')throw 'exact area setter';a.nodeValue='not a date';if(x.alt!=='not a date'||a.value!=='not a date')throw 'alt is plain reflection';x.removeAttribute('alt');if(x.alt!==''||a.ownerElement!==null||a.value!=='not a date')throw 'removed alt default';"#);}
#[test]
fn area_alt_inert_namespace_conversion_and_clone_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:area');if(!(x instanceof HTMLAreaElement)||x.alt!=='')throw 'inert area defaults';var calls=0;x.alt={toString:function(){calls++;x.setAttribute('alt','author');return 'R\udfffZ';}};if(calls!==1||x.alt!=='R\udfffZ'||x.getAttribute('alt')!==x.alt)throw 'once exact conversion';x.setAttributeNS('urn:foreign','alt','foreign');x.setAttributeNS(null,'ALT','upper');if(x.alt!=='R\udfffZ')throw 'null namespace exact local name';var clone=x.cloneNode(false);if(clone.alt!==x.alt)throw 'namespace clone';x.removeAttributeNS('urn:foreign','alt');x.removeAttributeNS(null,'ALT');clone.alt='independent';if(x.alt!=='R\udfffZ')throw 'independent copied metadata';"#);}

// Exact alt metadata preserves conversion, concrete brands and native authority.
#[test]
fn area_alt_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),old=x.getAttributeNode('alt'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.alt={toString:function(){calls++;x.removeAttribute('alt');x.setAttribute('alt','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('alt'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='2026-11-24'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.alt={toString:function(){x.setAttribute('alt','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.alt!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.alt=Symbol('area');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.alt!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.alt=value;if(x.alt!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='')throw 'metadata leaves displayed text';"#);
}
#[test]
fn area_alt_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),C=HTMLAreaElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'alt'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','area'),new Document().createElementNS('http://www.w3.org/1999/xhtml','AREA')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'alt',{value:'author',writable:true,configurable:true});if(x.alt!=='author'||a.get.call(x)!=='2026-11-24')throw 'canonical authority';a.set.call(x,'canonical');if(x.alt!=='author'||x.getAttribute('alt')!=='canonical')throw 'borrowed real setter';delete x.alt;if(x.alt!=='canonical'||Object.hasOwn(x,'alt'))throw 'restored inherited reflection';delete window.HTMLAreaElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}
#[test]
fn area_alt_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLAreaElement,a=Object.getOwnPropertyDescriptor(C.prototype,'alt'),calls=0;if(C===HTMLAreaElement||a.get.call(x)!=='2026-11-24')throw 'captured area accessor';"#);p.set_location(&crate::navigation::address("https://other-time.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://area-alt.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'area origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.
#[test]
fn area_alt_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.alt='Long canonical \ud800 DateTime replacement';",r"x.setAttribute('alt','Long canonical \ud800 DateTime replacement');",r"attr.value='Long canonical \ud800 DateTime replacement';",r"attr.nodeValue='Long canonical \ud800 DateTime replacement';",r"attr.textContent='Long canonical \ud800 DateTime replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.setAttribute('alt','2026-11-24');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('alt'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("alt writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='2026-11-24'||x.alt!=='2026-11-24'||watch.takeRecords().length)throw 'atomic alt writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.alt!=='Long canonical \ud800 DateTime replacement'||records.length!==1||records[0].oldValue!=='2026-11-24'||records[0].attributeName!=='alt'||x.getAttributeNode('alt')!==attr)throw 'fresh alt writer recovery';");
 }}}
}
#[test]
fn area_alt_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var time=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');time.alt='A\ud800Z';");let Value::Host(object)=p.runtime.execute("time;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert time handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('area').alt='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_alt_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_alt_get(object).is_ok());}}
}


#[test]
fn area_alt_native_and_inert_exact_attached_aliases_and_namespace(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.setAttribute('alt','2026-11-24');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('alt');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.alt!=='R\ud800'+writer||x.getAttributeNode('alt')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','alt','foreign');x.setAttributeNS(null,'ALT','upper');if(x.alt!=='R\ud800textContent'||x.getAttributeNodeNS(null,'alt')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'alt','alternative');if(x.alt!=='alternative'||a.value!==x.alt)throw 'null namespace writer';x.removeAttributeNS(null,'alt');if(x.alt!==''||a.ownerElement!==null||a.value!=='alternative')throw 'removed actual alt';"#);}
}
#[test]
fn area_alt_native_copy_import_and_neighbor_attribute_guards_remain_atomic(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),source=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');source.alt='actual';var neighbor=document.getElementById('neighbor');");
 run(&mut d,&mut f,&mut p,"var copy=x.cloneNode(false),imported=document.importNode(source,false);if(!(copy instanceof HTMLAreaElement)||!(imported instanceof HTMLAreaElement)||copy.parentNode!==null||imported.parentNode!==null||copy.ownerDocument!==document||imported.ownerDocument!==document||copy.alt!==x.alt||imported.alt!==source.alt||copy.getAttributeNode('alt')===x.getAttributeNode('alt')||imported.getAttributeNode('alt')===source.getAttributeNode('alt'))throw 'independent admitted area metadata copies';source.setAttribute('onclick','window.guard=1');");
 let area=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap();
 if let NodeKind::Element{attrs,..}=&mut d.nodes[area].kind{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=2".to_owned())});}
 p.state.rebuild(&d).unwrap();
 for code in ["x.cloneNode(false);","document.importNode(source,false);",r"neighbor.setAttribute('alt','A\ud800Z');"]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("not implemented")||e.contains("Import supports ordinary HTML containers and inert data nodes.")||e.contains("Unpaired attribute")||e.contains("active handlers"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.alt!=='actual'||x.alt!=='2026-11-24'||neighbor.value!=='seed'||neighbor.hasAttribute('alt'))throw 'preserved native and neighbor guards';");}
}

#[test]
fn area_alt_insert_before_method_preserves_ordinary_descriptor_deletion_and_saved_mutation(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var P=Node.prototype,a=Object.getOwnPropertyDescriptor(P,'insertBefore'),method=a.value,x=document.getElementById('area'),node=document.createElement('span');if(typeof method!=='function'||a.get!==undefined||!a.enumerable||!a.writable||!a.configurable||method.name!=='insertBefore'||method.length!==2||x.insertBefore!==method)throw 'ordinary insert descriptor';var caught=false;try{method.call({},node,x);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'insert concrete receiver';delete P.insertBefore;if(x.insertBefore!==undefined)throw 'deleted insert must not resurrect';if(method.call(document.body,node,x)!==node||node.nextSibling!==x||node.parentNode!==document.body||x.alt!=='2026-11-24')throw 'saved real insertion';Object.defineProperty(P,'insertBefore',a);Object.freeze(P);a=Object.getOwnPropertyDescriptor(P,'insertBefore');if(a.value!==method||a.writable||a.configurable||!a.enumerable||x.insertBefore!==method)throw 'frozen ordinary insert identity';"#);
}
